float read_next( ) {
  float * tmp;
  float return_val;

  #pragma omp single copyprivate(tmp)
  {
    tmp = (float *) malloc(sizeof(float));
  }  /* copies the pointer only */


  #pragma omp masked
  {
    scanf("%f", tmp);
  }

  #pragma omp barrier
  return_val = *tmp;
  #pragma omp barrier

  #pragma omp single nowait
  {
    free(tmp);
  }

  return return_val;
}

void gen_task (int &x) { // on orphaned task construct reference argument
  #pragma omp task // x is implicitly determined firstprivate(x)
  task_body (x);
}

void test (int &y, int &z) {
  #pragma omp parallel private(y)
  {
    y = z + 2;
    gen_task (y); // no matter if the argument is determined private
    gen_task (z); // or shared in the enclosing context.

    y++;          // each thread has its own int object y refers to
    gen_task (y);
  }
}

void default_none(int a) {
  const int c = 1;
  int i = 0;

  #pragma omp parallel default(none) private(a) shared(z, c)
  {
     int j = omp_get_num_threads();
          /* O.K.  - j is declared within parallel region */
     a = z[j];   /* O.K.  - a is listed in private clause */
                 /*       - z is listed in shared clause */
     x = c;      /* O.K.  - x is threadprivate */
                 /*       - c has const-qualified type and
                              is listed in shared clause */
     z[i] = y;   /* Error - cannot reference i or y here */

  #pragma omp for firstprivate(y)
         /* Error - Cannot reference y in the firstprivate clause */
     for (i=0; i<10 ; i++) {
        z[i] = i; /* O.K. - i is the loop iteration variable */
     }

     z[i] = y;   /* Error - cannot reference i or y here */
  }
}

void comp_poly(int N, double x, double c[]) {
   // x:    input: value of x for which to eval the polynomial
   // c[N]: input: the coefficients
   double x0 = 1.0;       // initial value x^0 == 1
   double xi;             // x^i
   double result;         // accumulator for the result

   // Case 1: induction clause
   xi = x0;
   result = 0.0;
   #pragma omp parallel for reduction(+: result) induction(step(x),*: xi)
   for (int i = 0; i < N; i++) {
      result += c[i] * xi;
      xi *= x;
   }
   printf("C1: result = %f, xn = %f\n", result, xi);

   // Case 2: inscan reduction
   xi = x0;
   result = 0.0;
   #pragma omp parallel for reduction(+: result) reduction(inscan,*: xi)
   for (int i = 0; i < N; i++) {
      result += c[i] * xi;
      #pragma omp scan exclusive(xi)
      xi *= x;
   }
   printf("C2: result = %f, xn = %f\n", result, xi);

   // Case 3: closed form
   result = 0.0;
   #pragma omp parallel for reduction(+: result) lastprivate(xi)
   for (int i = 0; i < N; i++) {
      xi = x0 * pow(x, i);     // induction operation in closed form
      result += c[i] * xi;
      xi *= x;
   }
   printf("C3: result = %f, xn = %f\n", result, xi);
}

void processPointsInLine(Point Start, int NumberOfPoints, 
                         float Separation) {
  Point P = Start;
  #pragma omp parallel for induction(step(Separation), next : P)
  for (int i = 0; i < NumberOfPoints; ++i) {
    process(P);
    P = P.nextPoint(Separation);
  }
}

int main() {
  Point Start(1.0f, -2.0f, 0.5f);
  processPointsInLine(Start, 100, 0.25f);
  return 0;
}

void lastpriv (int n, float *a, float *b)
{
  int i;

  #pragma omp parallel
  {
    #pragma omp for lastprivate(i)
    for (i=0; i<n-1; i++)
      a[i] = b[i] + b[i+1];
  }

  a[i]=b[i];      /* i == n-1 here */
}

float condlastprivate(float *a, int n)
{
   float x = 0.0f;

   #pragma omp parallel for simd lastprivate(conditional: x)
   for (int k = 0; k < n; k++) {
      if (a[k] < 108.5 || a[k] > 208.5) {
         x = sinf(a[k]);
      }
   }

   return x;
}

int do_red(int n, int *v)
{
  int sum_v = 0;     // sum_v is private

  #pragma omp for reduction(+: sum_v)
  for (int i = 0; i < n; i++) {
    sum_v += v[i];
  }
  return sum_v;
}

int main(void)
{
  int v[N];
  for (int i = 0; i < N; i++)
    v[i] = i;

  #pragma omp parallel
  {
    int s_v = do_red(N, v);
    printf("myid %d: sum of v = %d\n", omp_get_thread_num(), s_v);
  }
  return 0;
}

void do_red(int n, int *v, int &sum_v)
{
  sum_v = 0;     // sum_v is private
  #pragma omp for reduction(original(private),+: sum_v)
  for (int i = 0; i < n; i++) {
    sum_v += v[i];
  }
}

int main(void)
{
  int v[N];
  for (int i = 0; i < N; i++)
    v[i] = i;

  #pragma omp parallel
  {
    int s_v;     // s_v is private
    do_red(N, v, s_v);
    printf("myid %d: sum of v = %d\n", omp_get_thread_num(), s_v);
  }
  return 0;
}

int main(void)
{
  int x;

  x = 0;
  // parallel reduction on shared x
  #pragma omp parallel reduction(+: x) num_threads(strict: 4)
  {
    #pragma omp for reduction(+: x)   // reduction on private x
      for (int i = 0; i < 10; i++)
        x++;
  }
  printf("x = %d\n", x);    // should print 40, with 4 threads
  return 0;
}

