int main(void)
{
   int c[N], tmp;
   int x = 0;

   // initialization
   for (int k = 0; k < N; k++)
      c[k] = k + 1;

   // c[k] is used for both input and output of scan results
   #pragma omp parallel for simd reduction(inscan,+: x) private(tmp)
   for (int k = 0; k < N; k++) {
      // initialization phase
      tmp = c[k];
      #pragma omp scan init_complete

      // scan (output) phase - cannot use tmp here
      c[k] = x;

      #pragma omp scan exclusive(x)

      // input phase - can use tmp here
      x += tmp;
   }

   printf("x = %d, c[0:3] = %d %d %d\n", x, c[0], c[1], c[2]);
   //           5050,       0  1  3

   return 0;
}

void do_work(int n, float a[], float &s)
{
   float loc_s = 0.0f;        // local sum
   static int nthrs;
   #pragma omp for
      for (int i = 0; i < n; i++)
         loc_s += a[i];
   #pragma omp single
   {
      s = 0.0f;               // total sum
      nthrs = 0;
   }
   #pragma omp scope reduction(+:s,nthrs)
   {
      s += loc_s;
      nthrs++;
   }
   #pragma omp masked
      printf("total sum = %f, nthrs = %d\n", s, nthrs);
}

float work(int n, float a[])
{
   float s;
   #pragma omp parallel
   {
      do_work(n, a, s);
   }
   return s;
}

