   const int accessible = omp_target_is_accessible(ptr, buf_size, dev);

   #pragma omp metadirective \
      when(user={condition(accessible)}: target firstprivate(ptr) ) \
      otherwise(                         target map(ptr[:n])      )
   {
      do_work(ptr, n);
   } 

   free(ptr);
   return 0;
}

