  #pragma omp target 
  {
     x++;
  }
  if( x != 0 ) pass = false;

  x = 0;
  // Case 2: ptr is firstprivate
  //         (uses address assigned in host data environment)
  #pragma omp target
  {
     (*ptr)++;
  }
  if( x != 1 ) pass = false;

  x = 0;
  // Case 3: ref and its object are mapped
  #pragma omp target
  {
    ref++;
  }
  if( x != 1 ) pass = false;

  // Verification
