void task_dep(int N)
{
  int i, v, R;

  #pragma omp parallel private(i,v) shared(R)
  #pragma omp single
  {
    // CASE 1: tasks with inout dependence type.
    //         tasks are serialized here.
    R = 0;
    for ( i = 0; i < N; i++ ) {
      #pragma omp task depend(inout: R)    // T1
      {
        v = f(i);
        R += v;
      }
    }

    #pragma omp task depend(in: R)         // T2
      printf("result is %d\n", R);
    #pragma omp taskwait      // to avoid race with CASE 2

    // CASE 2: tasks with inoutset dependence type.
    //         tasks are executed concurrently.
    R = 0;
    for ( i = 0; i < N; i++ ) {
      #pragma omp task depend(inoutset: R) // T3
      {
        v = f(i);
        #pragma omp atomic
        R += v;
      }
    }

    #pragma omp task depend(in: R)         // T4
      printf("result is %d\n", R);
  }
}

void matmul_depend(int BS, float A[N][N], float B[N][N],
                   float C[N][N])
{
   int i, j, k, ii, jj, kk;
   for (i = 0; i < N; i+=BS) {
      for (j = 0; j < N; j+=BS) {
         for (k = 0; k < N; k+=BS) {
// Note 1: i, j, k, A, B, C are firstprivate by default
// Note 2: A, B and C are just pointers
#pragma omp task private(ii, jj, kk) \
            depend ( in: A[i:BS][k:BS], B[k:BS][j:BS] ) \
            depend ( inout: C[i:BS][j:BS] )
            for (ii = i; ii < i+BS; ii++ )
               for (jj = j; jj < j+BS; jj++ )
                  for (kk = k; kk < k+BS; kk++ )
                     C[ii][jj] = C[ii][jj] + A[ii][kk] * B[kk][jj];
         }
      }
   }
}

